    need(filehash(Path(__file__))==SOURCE_SHA,'ONEFILE_SOURCE_PIN')
    for path,digest in plan['input_pins'].items():need(filehash(path)==digest,'RECIPE_OR_ENV_DRIFT')
    for path,expected in plan['guards'].items():
        info=MODULE.regular(path);now={'sha256':filehash(path),'uid':info.st_uid,'gid':info.st_gid,'mode':stat.S_IMODE(info.st_mode)}
        need(now==expected,'GUARD_DRIFT')
    for unit in ['synapse-sync.service','synapse-sync.timer']:
        need(run(['systemctl','show',unit,'-p','ActiveState','--value'],'sync').stdout.strip()==b'inactive','SYNC_ACTIVE')
    need(run(['systemctl','is-enabled','synapse-sync.timer'],'sync-enabled',accepted=(0,1,3)).stdout.strip()==b'disabled','SYNC_TIMER_ENABLED')
    need(not Path('/usr/local/sbin/synapse-sync').exists() and not Path('/usr/local/sbin/synapse-sync').is_symlink(),'UNEXPECTED_SYNC_PATH')
    need(run(['git','--no-optional-locks','-C',str(REPO),'rev-parse','HEAD'],'checkout-head').stdout.strip()==MODULE.HOST_HEAD.encode(),'CHECKOUT_HEAD_DRIFT')
