    result={}
    for service,db in plan['databases'].items():
        target=folder/service;target.mkdir(mode=0o700);saved={}
        for suffix in ['', '-wal','-shm']:
            path=Path(str(db)+suffix);key=path.name
            if not path.exists():saved[key]=None;continue
            need(path.is_file() and not path.is_symlink(),'RAW_FILE_TYPE');st=path.stat();dest=target/key
            with path.open('rb') as a,dest.open('xb') as b:shutil.copyfileobj(a,b,65536);b.flush();os.fsync(b.fileno())
            dest.chmod(0o600);now=path.stat()
            need((st.st_dev,st.st_ino,st.st_size,st.st_mtime_ns)==(now.st_dev,now.st_ino,now.st_size,now.st_mtime_ns) and filehash(dest)==filehash(path),'RAW_CHANGED_DURING_COPY')
            saved[key]={'sha256':filehash(dest),'mode':stat.S_IMODE(st.st_mode),'uid':st.st_uid,'gid':st.st_gid}
        result[service]=saved
