    entries={Path(e['path']).name:e for e in manifest['entries'] if e['scope']=='host-static'}
    need(set(entries)==set(order),'STATIC_EXACT_SCOPE')
    for name in order:
        entry=entries[name];path=REPO/entry['path'];need(not path.exists() and not path.is_symlink(),'STATIC_PUBLISH_CAS')
        data=(N/'package478'/entry['payload']).read_bytes();need(sha(data)==entry['after']['sha256'],'STATIC_PAYLOAD_PIN')
        st=path.parent.stat();tmp=path.with_name(name+'.sb478-r1.tmp');intents.append((path,sha(data)))
        event('STATIC_INTENT',path=str(path));
        with tmp.open('xb') as f:f.write(data);f.flush();os.fsync(f.fileno())
        os.chown(tmp,st.st_uid,st.st_gid);tmp.chmod(0o644);os.replace(tmp,path)
