def rollback_static(intents):
    conflicts=[]
    for path,digest in reversed(intents):
        if not path.exists() and not path.is_symlink():continue
        if not path.is_symlink() and path.is_file() and filehash(path)==digest:path.unlink()
        else:conflicts.append(str(path))
    return conflicts
